<section class="page-banner"><div class="container"><span class="eyebrow">CONTACT & LOCATIONS</span><h1>Let’s get to work.</h1><p>Product enquiries, distribution opportunities and company information.<br>Connect with our team.</p></div></section><section class="section container"><div class="contact-grid"><?php foreach($contacts as $contact): ?><article class="contact-card"><span class="eyebrow">GET IN TOUCH</span><h2><?= e($contact['title']) ?></h2><?php if($contact['address']): ?><div><span class="field-label">ADDRESS</span><p><?= nl2br(e($contact['address'])) ?></p></div><?php endif; ?><?php if($contact['email']): ?><div><span class="field-label">EMAIL</span><a href="mailto:<?= e($contact['email']) ?>"><?= e($contact['email']) ?> ↗</a></div><?php endif; ?><?php if($contact['phone']): ?><div><span class="field-label">PHONE</span><a href="tel:<?= e(preg_replace('/[^+0-9]/','',$contact['phone'])) ?>"><?= e($contact['phone']) ?></a></div><?php endif; ?><?php if($contact['hours']): ?><div><span class="field-label">OPENING HOURS</span><p><?= e($contact['hours']) ?></p></div><?php endif; ?></article><?php endforeach; ?><?php if(!$contacts): ?><p class="empty">Contact details are being updated. Please check back soon.</p><?php endif; ?></div></section>
